# Spin up two tiny TCP listeners via node, then run the health check
node -e "
const net = require('net');

let ready = 0;
function maybeRun() {
  if (++ready < 2) return;
  const { execFileSync } = require('child_process');
  try {
    const out = execFileSync('bash', ['healthcheck.sh'], { encoding: 'utf8' });
    process.stdout.write(out);
    process.stdout.write('Exit code: 0\n');
  } catch(e) {
    process.stdout.write(e.stdout || '');
    process.stdout.write('Exit code: ' + e.status + '\n');
  }
  process.exit(0);
}

[3000, 8080].forEach(port => {
  const srv = net.createServer(c => c.end());
  srv.listen(port, '127.0.0.1', () => { maybeRun(); });
});
"

# Simulate DOWN scenario by checking a port nothing listens on
HEALTH_CHECK_TIMEOUT=1 node -e "
const { execFileSync } = require('child_process');
const net = require('net');

// Only open port 3000; leave 8080 closed
const srv = net.createServer(c => c.end());
srv.listen(3000, '127.0.0.1', () => {
  try {
    // Override port list inline by temporarily monkey-patching env
    const out = execFileSync('bash', ['-c',
      'HEALTH_CHECK_TIMEOUT=1 bash healthcheck.sh'
    ], { encoding: 'utf8', env: { ...process.env, HEALTH_CHECK_TIMEOUT: '1' } });
    process.stdout.write(out);
  } catch(e) {
    process.stdout.write(e.stdout || '');
    process.stderr.write('Exit code: ' + e.status + '\n');
  }
  srv.close();
  process.exit(0);
});
"
